\label{lem:moving-trunc}
Suppose \(\mu_n\xrightarrow{\psi}\mu\), \(c_n\to c\in\mathbb R\), and \(\mu(\{c\})=0\).
Then
\[
 \mu_n\!\restriction_{(-\infty,c_n]}\xrightarrow{\psi}
 \mu\!\restriction_{(-\infty,c]},\qquad
 \mu_n\!\restriction_{(c_n,\infty)}\xrightarrow{\psi}
 \mu\!\restriction_{(c,\infty)}.
\]
The same statement holds for the open-left convention.

\label{cor:profile-modes}
If \(\mu_n\xrightarrow{\psi}\mu\), then:
\begin{enumerate}[label=(\alph*),leftmargin=2.2em]
\item \(H_G^\le(\mu_n,c)\to H_G^\le(\mu,c)\) at every atom-free \(c\);
\item for every compact \(K\subset\mathbb R\) and \(1\le p<\infty\),
\[
 \int_K|H_G^\le(\mu_n,c)-H_G^\le(\mu,c)|^p\,dc\to0;
\]
\item if \(\mu\) is atomless, then convergence is uniform on \(\overline{\mathbb R}\).
\end{enumerate}

\label{def:epi}
Functions \(f_n:\overline{\mathbb R}\to\mathbb R\cup\{+\infty\}\) epi-converge to \(f\) if:
\begin{enumerate}[label=(\roman*),leftmargin=2.2em]
\item for every \(c_n\to c\),
\(\liminf_n f_n(c_n)\ge f(c)\);
\item for every \(c\), there exists \(c_n\to c\) such that
\(\limsup_n f_n(c_n)\le f(c)\).
\end{enumerate}

\label{thm:epi}
If \(\mu_n\xrightarrow{\psi}\mu\), then
\begin{equation}\label{eq:epi-conv}
 \underline H_G(\mu_n,\cdot)
 \xrightarrow{\mathrm{epi}}
 \underline H_G(\mu,\cdot)
 \qquad\text{on }\overline{\mathbb R}.
\end{equation}
